class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        s1_cnt, s2_cnt, s2_ptr, recall = 0, 0, 0, {}
        while s1_cnt < n1:
            s1_cnt += 1
            for char in s1:
                if char == s2[s2_ptr]:
                    s2_ptr += 1
                    if s2_ptr == len(s2):
                        s2_ptr, s2_cnt = 0, s2_cnt + 1
            if s2_ptr in recall:
                prev_s1_cnt, prev_s2_cnt = recall[s2_ptr]
                cycle_s1, cycle_s2 = s1_cnt - prev_s1_cnt, s2_cnt - prev_s2_cnt
                num_cycles = (n1 - s1_cnt) // cycle_s1
                s1_cnt += num_cycles * cycle_s1
                s2_cnt += num_cycles * cycle_s2
                recall = {}
            else:
                recall[s2_ptr] = (s1_cnt, s2_cnt)
        return s2_cnt // n2

