class Solution:
    def palindromePairs(self, words: List[str]) -> List[List[int]]:
        backward, res = {w[::-1]: i for i, w in enumerate(words)}, []
        for i, word in enumerate(words):
            for j in range(len(word) + 1):
                pre, suf = word[:j], word[j:]
                if pre == pre[::-1] and suf in backward and backward[suf] != i:
                    res.append([backward[suf], i])
                if j < len(word) and suf == suf[::-1] and pre in backward and backward[pre] != i:
                    res.append([i, backward[pre]])
        return res

