from functools import lru_cache
class Solution:
    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        @lru_cache(None)
        def dp(i, prev, ct, k):
            if k < 0: return 101
            if i == len(s): return 0
            if s[i] == prev:
