class Solution:
    def numPermsDISequence(self, s: str) -> int:
        dp, mod = [1], 10**9 + 7
        for i, c in enumerate(s):
            nxt, cur = [0] * (i + 2), 0
            if c == 'I':
                for j in range(1, i + 2):
                    cur = (cur + dp[j-1]) % mod
                    nxt[j] = cur
            else:
                for j in range(i, -1, -1):
                    cur = (cur + dp[j]) % mod
                    nxt[j] = cur
            dp = nxt
        return sum(dp) % mod

class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        s1_cnt, s2_cnt, index = 0, 0, 0
        recall = {}
        while s1_cnt < n1:
            s1_cnt += 1
            for char in s1:
                if char == s2[index]:
                    index += 1
                    if index == len(s2):
                        s2_cnt += 1
                        index = 0
            if index in recall:
                p_s1, p_s2 = recall[index]
                c_s1, c_s2 = s1_cnt - p_s1, s2_cnt - p_s2
