from functools import lru_cache
from typing import List

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        R, C = len(pizza), len(pizza[0])
        pref = [[0] * (C + 1) for _ in range(R + 1)]
        for r in range(R - 1, -1, -1):
            for c in range(C - 1, -1, -1):
                pref[r][c] = (pizza[r][c] == 'A') + pref[r+1][c] + pref[r][c+1] - pref[r+1][c+1]

        @lru_cache(None)
        def dp(rem, r, c):
            if pref[r][c] < rem: return 0
            if rem == 1: return 1
            res = 0
            for nr in range(r + 1, R):
                if pref[r][c] > pref[nr][c]:
                    res = (res + dp(rem - 1, nr, c)) % 1000000007
            for nc in range(c + 1, C):
                if pref[r][c] > pref[r][nc]:
                    res = (res + dp(rem - 1, r, nc)) % 1000000007
            return res

        return dp(k, 0, 0)

