                if power >= target:
                    continue
                elif power + k < target:
                    ans = False
                    break
                else:
                    diff = target - power
                    power = target
                    stations[min(i + r, n - 1)] += diff
                    k -= diff
                    newStations[min(i + r, n - 1)] += diff
            for i in newStations:
                stations[i] -= newStations[i]
            return ans
