class Solution:
    def numPermsDISequence(self, s: str) -> int:
        @lru_cache(None)
        def dfs(i, j):
            if i == 0: return 1
            if s[i-1] == 'I':
                return sum(dfs(i-1, k) for k in range(j)) % (10**9 + 7)
            return sum(dfs(i-1, k) for k in range(j, i)) % (10**9 + 7)
        return sum(dfs(len(s), j) for j in range(len(s) + 1)) % (10**9 + 7)

