class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if not set(s2).issubset(set(s1)): return 0
        s1 = "".join(c for c in s1 if c in set(s2))
        rec, track, ct, ptr, start = [0], {}, 0, 0, 0
        while True:
            for char in s2:
                ptr = s1.find(char, start)
                if ptr == -1:
                    ct += 1
                    ptr = s1.find(char)
                start = ptr + 1
            rec.append(ct + 1)
            if rec[-1] > n1: return (len(rec) - 2) // n2
            if ptr in track:
                prev = track[ptr]
                c_s1, c_s2 = rec[-1] - rec[prev], (len(rec) - 1) - prev
                num, rem = divmod(n1 - rec[prev], c_s1)
                res = prev + num * c_s2
                for i in range(prev + 1, len(rec)):
                    if rec[i] - rec[prev] <= rem: res += 1
                return res // n2
            track[ptr] = len(rec) - 1

