import collections
from typing import List

class Solution:
    def findSubstring(self, s: str, words: List[str]) -> List[int]:
        if not s or not words: return []
        wl, n, total = len(words[0]), len(s), len(words)
        occ, res = collections.Counter(words), []
        for i in range(wl):
            left, curr, count = i, collections.Counter(), 0
            for j in range(i, n - wl + 1, wl):
                word = s[j:j+wl]
                if word in occ:
                    curr[word] += 1
                    count += 1
                    while curr[word] > occ[word]:
                        curr[s[left:left+wl]] -= 1
                        count -= 1
                        left += wl
                    if count == total: res.append(left)
                else:
                    curr.clear()
                    count, left = 0, j + wl
        return res

