class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        s1_cnt, s2_cnt, ptr, recall = 0, 0, 0, {}
        while s1_cnt < n1:
            s1_cnt += 1
            for char in s1:
                if char == s2[ptr]:
                    ptr += 1
                    if ptr == len(s2):
                        s2_cnt, ptr = s2_cnt + 1, 0
            if ptr in recall:
                p1, p2 = recall[ptr]
                q = (n1 - s1_cnt) // (s1_cnt - p1)
                s1_cnt += q * (s1_cnt - p1)
                s2_cnt += q * (s2_cnt - p2)
                recall = {}
            else: recall[ptr] = (s1_cnt, s2_cnt)
        return s2_cnt // n2

