            if i == n or n - i <= k: return 0
            res = dp(i + 1, k - 1)
            cnt, diff = 0, 0
            for j in range(i, n):
                if s[j] == s[i]: cnt += 1
                else: diff += 1
                if diff > k: break
                ln = 1 if cnt == 1 else (2 if cnt < 10 else (3 if cnt < 100 else 4))
