class Solution:
    def numPermsDISequence(self, s: str) -> int:
        n, mem = len(s), {}
        def dfs(i, val):
            if i == n: return 1
            if (i, val) in mem: return mem[(i, val)]
            if s[i] == "D":
                res = sum(dfs(i + 1, k) for k in range(val))
            else:
                res = sum(dfs(i + 1, k) for k in range(val, n - i))
            mem[(i, val)] = res % (10**9 + 7)
            return mem[(i, val)]
        return sum(dfs(0, j) for j in range(n + 1)) % (10**9 + 7)

