from collections import defaultdict, deque
from typing import List

class Solution:
    def findAllRecipes(self, recepies: List[str], ingredients: List[List[str]], supplies: List[str]) -> List[str]:
        adj, indegree = defaultdict(list), {r: len(ings) for r, ings in zip(recepies, ingredients)}
        for r, ings in zip(recepies, ingredients):
            for ing in ings:
                adj[ing].append(r)

        q, flst = deque(supplies), []
        while q:
            u = q.popleft()
            for v in adj.get(u, []):
                indegree[v] -= 1
                if indegree[v] == 0:
                    flst.append(v)
                    q.append(v)
        return flst

class Solution:
    def splitListToParts(self, head: Optional[ListNode], k: int) -> List[Optional[ListNode]]:
        length, ptr = 0, head
        while ptr:
            length += 1
            ptr = ptr.next

        maxi, remain = divmod(length, k)
        l, ptr = [], head
        for i in range(k):
            l.append(ptr)
            size = maxi + (1 if i < remain else 0)
            if size:
                for _ in range(size - 1):
                    ptr = ptr.next
                ptr.next, ptr = None, ptr.next
        return l

