import collections
from typing import List

class Solution:
    def findSubstring(self, s: str, words: List[str]) -> List[int]:
        if not s or not words: return []
        wlen, n_words, res = len(words[0]), len(words), []
        occ = collections.Counter(words)
        for k in range(wlen):
            left = right = k
            track = collections.Counter()
            while right + wlen <= len(s):
                w = s[right:right + wlen]
                right += wlen
                if w in occ:
                    track[w] += 1
                    while track[w] > occ[w]:
                        track[s[left:left + wlen]] -= 1
                        left += wlen
                    if right - left == wlen * n_words:
                        res.append(left)
                else:
                    track.clear()
                    left = right
        return res

