class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        forbidden_set = set(forbidden)
        res, n = 0, len(word)
        right = n
        for i in range(n - 1, -1, -1):
            for length in range(1, 11):
                if i + length > right:
                    break
                if word[i:i + length] in forbidden_set:
                    right = i + length - 1
                    break
            res = max(res, right - i)
        return res

