    def validArrangement(self, pairs: List[List[int]]) -> List[List[int]]:
        graph, degree = defaultdict(list), defaultdict(int)
        for x, y in pairs:
            graph[x].append(y)
            degree[x] += 1
            degree[y] -= 1

        start = pairs[0][0]
        for k in degree:
