            for char in s1:
                if char == s2[i]:
                    i += 1
                    if i == len(s2):
                        s2_cnt += 1
                        i = 0
            if i in memo:
                prev_s1, prev_s2 = memo[i]
                cnt = (n1 - s1_cnt) // (s1_cnt - prev_s1)
                s1_cnt += cnt * (s1_cnt - prev_s1)
                s2_cnt += cnt * (s2_cnt - prev_s2)
                memo = {}
            else:
                memo[i] = (s1_cnt, s2_cnt)
        return s2_cnt // n2

