class Solution:
    def numMovesStonesII(self, stones: List[int]) -> List[int]:
        stones.sort()
        n = len(stones)
        mx = max(stones[n - 1] - stones[1] - n + 2, stones[n - 2] - stones[0] - n + 2)
        mi, i = n, 0
        for j in range(n):
            while stones[j] - stones[i] >= n:
                i += 1
            if j - i + 1 == n - 1 and stones[j] - stones[i] == n - 2:
                mi = min(mi, 2)
            else:
