class Solution:
    def numPermsDISequence(self, s: str) -> int:
        mem = {}
        def dfs(i, val):
            if i == 0: return 1
            if (i, val) in mem: return mem[i, val]
            if s[i-1] == "I":
                p = sum(dfs(i-1, k) for k in range(val))
            else:
                p = sum(dfs(i-1, k) for k in range(val, i))
            mem[i, val] = p % 1000000007
            return mem[i, val]
        n = len(s)
        return sum(dfs(n, j) for j in range(n + 1)) % 1000000007

