from functools import lru_cache

class Solution:
    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        @lru_cache(None)
        def dp(i, k, prev, count):
            if k < 0: return 101
            if i == len(s): return 0
            delete = dp(i + 1, k - 1, prev, count)
            if s[i] == prev:
                keep = dp(i + 1, k, prev, count + 1) + (1 if count in (1, 9, 99) else 0)
            else:
                keep = dp(i + 1, k, s[i], 1) + 1
            return min(delete, keep)
        return dp(0, k, "", 0)

