import math

class Solution:
    def countAnagrams(self, s: str) -> int:
        mod = 10**9 + 7
        res = 1
        for word in s.split():
            d = {}
            for char in word:
                d[char] = d.get(char, 0) + 1

            denom = 1
            for count in d.values():
                denom *= math.factorial(count)
            res = (res * (math.factorial(len(word)) // denom)) % mod
        return res

