from functools import cache
from typing import List

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        R, C, MOD = len(pizza), len(pizza[0]), 10**9 + 7
        s = [[0] * (C + 1) for _ in range(R + 1)]
        for r in range(R - 1, -1, -1):
            for c in range(C - 1, -1, -1):
                s[r][c] = (pizza[r][c] == 'A') + s[r+1][c] + s[r][c+1] - s[r+1][c+1]

        @cache
        def dp(r, c, k):
            if s[r][c] < k: return 0
            if k == 1: return 1
            res = 0
            for nr in range(r + 1, R):
                if s[r][c] - s[nr][c] > 0:
                    res = (res + dp(nr, c, k - 1)) % MOD
            for nc in range(c + 1, C):
                if s[r][c] - s[r][nc] > 0:
                    res = (res + dp(r, nc, k - 1)) % MOD
            return res

        return dp(0, 0, k)

